// Check if invitation scheduler is already running (Patch 9)
// Convert Settings sheet rows (key/value pairs) into a lookup object
const settingsRows = $input.all();
const settings = {};
for (const row of settingsRows) {
  if (row.json.key) settings[row.json.key] = row.json.value;
}

const locked = settings['invitation_scheduler_locked'] === 'true';
const lockTime = settings['invitation_scheduler_lock_time'] ? new Date(settings['invitation_scheduler_lock_time']) : null;
const staleLimitMin = parseInt(settings['scheduler_stale_lock_minutes'] || '10');
const withdrawalDays = parseInt(settings['invitation_withdrawal_days'] || '7');
const retryLimit = parseInt(settings['invite_retry_limit'] || '1');
const consecutivePauseThreshold = parseInt(settings['error_consecutive_pause_threshold'] || '5');

let shouldRun = true;
let reason = 'ok';

if (locked && lockTime) {
  const minutesLocked = (Date.now() - lockTime.getTime()) / 60000;
  if (minutesLocked < staleLimitMin) {
    shouldRun = false;
    reason = `Scheduler locked (${Math.round(minutesLocked)}m ago, threshold ${staleLimitMin}m)`;
  } else {
    reason = 'stale_lock_reset';
  }
} else if (locked && !lockTime) {
  reason = 'stale_lock_no_time_reset';
}

return [{ json: { shouldRun, reason, settings, withdrawalDays, retryLimit, consecutivePauseThreshold } }];

// Filter rows eligible for invitation send
// Checks: campaign running, account active & healthy, daily limit not exceeded
// Returns one item per eligible row with all context needed

const readyRows = $('Read Ready Rows').all().map(r => r.json);
const accounts = $('Read Accounts').all().map(r => r.json);
const runningCampaigns = $('Read Running Campaigns').all().map(r => r.json);

// Build lookup maps
const campaignMap = {};
for (const c of runningCampaigns) {
  campaignMap[String(c.campaign_id)] = c;
}
const accountMap = {};
for (const a of accounts) {
  accountMap[a.account_name] = a;
}

const eligible = [];
const skipped = [];

for (const row of readyRows) {
  // Must be in a running campaign
  const campaign = campaignMap[String(row.campaign_id)];
  if (!campaign) {
    skipped.push({ row_id: row.row_id, reason: 'campaign_not_running' });
    continue;
  }

  // Account must exist
  const account = accountMap[row.sending_account];
  if (!account) {
    skipped.push({ row_id: row.row_id, reason: 'account_not_found' });
    continue;
  }

  // Account must be active
  if (account.status !== 'active') {
    skipped.push({ row_id: row.row_id, reason: `account_status_${account.status}` });
    continue;
  }

  // Check stale counter — if reset_date != today, counters are stale, treat as 0
  const today = new Date().toISOString().split('T')[0];
  const sentToday = account.reset_date === today
    ? parseInt(account.connections_sent_today || '0')
    : 0;
  const dailyLimit = parseInt(account.connections_daily_limit || '10');

  if (sentToday >= dailyLimit) {
    skipped.push({ row_id: row.row_id, reason: 'daily_limit_reached' });
    continue;
  }

  eligible.push({
    ...row,
    // Join campaign messaging fields so personalizeText has them available
    connection_note: campaign.connection_note || '',
    message_1: campaign.message_1 || '',
    message_2: campaign.message_2 || '',
    message_3: campaign.message_3 || '',
    message_2_delay_hours: campaign.message_2_delay_hours || '',
    message_3_delay_hours: campaign.message_3_delay_hours || '',
    _account: account,
    _sentToday: sentToday,
    _dailyLimit: dailyLimit
  });
}

if (eligible.length === 0) {
  return [{ json: { eligible: false, total: readyRows.length, skipped: skipped.length } }];
}

return eligible.map(row => ({ json: row }));

// Extract provider_id from profile lookup response and prepare invite payload
// GET /api/v1/users/{identifier} returns a direct profile object with top-level provider_id
const profileResponse = $input.first().json;
const rowData = $('Filter Eligible Rows').item.json;

// The response is a direct LinkedIn profile object — provider_id is at top level
// (LinkedIn Classic: starts with 'ACo', Sales Nav: 'ACw', Recruiter: 'AE')
const providerId = profileResponse.provider_id || null;

if (!providerId) {
  // Cannot send invite without provider_id — will be marked failed downstream
  return [{ json: { ...rowData, _provider_id_resolved: false, _error: 'Could not resolve provider_id from LinkedIn URL' } }];
}

// Replace {{variable}} placeholders with actual prospect values before sending to UniPile.
// UniPile performs its own {variable} single-brace substitution which corrupts double-brace
// templates (e.g. {{first_name}} becomes {Veer }). We resolve all {{}} here so UniPile
// receives plain text with no template syntax remaining.
function personalizeText(template, prospect) {
  if (!template) return '';
  const firstName = (prospect.first_name || '').trim();
  const lastName = (prospect.last_name || '').trim();
  return template
    .replace(/\{\{first_name\}\}/gi, firstName)
    .replace(/\{\{last_name\}\}/gi, lastName)
    .replace(/\{\{full_name\}\}/gi, [firstName, lastName].filter(Boolean).join(' '))
    .replace(/\{\{company_name\}\}/gi, (prospect.company_name || '').trim())
    .replace(/\{\{title\}\}/gi, (prospect.title || '').trim());
}

const connectionNotePersonalized = personalizeText(rowData.connection_note || '', rowData);

return [{ json: { ...rowData, _provider_id_resolved: true, _resolved_provider_id: providerId, _connection_note_personalized: connectionNotePersonalized } }];

// Determine if invite was sent successfully and build update payload
const response = $input.first().json;
const rowData = $('Store Provider ID and Send Invite').item.json;

// Check HTTP status — UniPile returns 201 for successful invite send
const statusCode = response.statusCode || 200;
const success = statusCode >= 200 && statusCode < 300;

const now = new Date().toISOString();
const withdrawalDays = parseInt($('Check Scheduler Lock').first().json.settings['invitation_withdrawal_days'] || '7');
const withdrawalEligibleAt = new Date(Date.now() + withdrawalDays * 24 * 3600 * 1000).toISOString();

if (success) {
  return [{
    json: {
      _success: true,
      _row_id: rowData.row_id,
      _account_name: rowData.sending_account,
      _account_unipile_id: rowData._account.unipile_id,
      // Fields to update on Database row
      db_updates: {
        row_id: rowData.row_id,
        provider_id: rowData._resolved_provider_id,
        connection_request_status: 'sent',
        connection_request_time: now,
        withdrawal_eligible_at: withdrawalEligibleAt,
        retry_count: '0',
        failure_reason: '',
        last_updated: now,
        lifecycle_state: 'invite_sent'  // LAST — Patch 11
      },
      // Data for Activity Log
      activity: {
        timestamp: now,
        event_type: 'invitation_sent',
        campaign_id: rowData.campaign_id,
        campaign_name: rowData.campaign_name,
        prospect_linkedin_url: rowData.linkedin_url,
        prospect_first_name: rowData.first_name,
        sending_account: rowData.sending_account,
        description: `Invitation sent to ${rowData.first_name} ${rowData.last_name} at ${rowData.company_name}`
      }
    }
  }];
} else {
  // Failure — increment error counts
  const errorBody = JSON.stringify(response.body || response);
  return [{
    json: {
      _success: false,
      _row_id: rowData.row_id,
      _account_name: rowData.sending_account,
      _error_detail: errorBody,
      db_updates: {
        row_id: rowData.row_id,
        retry_count: String(parseInt(rowData.retry_count || '0') + 1),
        failure_reason: `invite_send_failed: HTTP ${statusCode}`,
        last_updated: now,
        lifecycle_state: 'failed'  // LAST — Patch 11
      }
    }
  }];
}
